#[inline]
fn destack_os_mount_list_replay(
    context: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeArray<MountEntry>,
) -> RuntimeResult<()> {
    context.replay().run_binding_with_policy(
        OS_MOUNT_LIST,
        context.replay_payload_for(OS_MOUNT_LIST)?,
        || match world {
            RuntimeWorld::Host => unsafe { platform_native::destack_os_list(context, out) },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_os_list(context, out)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded_raw = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item = *result_recorded_item_value;
                    let result_recorded_item_recorded_source =
                        unsafe { result_recorded_item.source.as_str()? }.to_string();
                    let result_recorded_item_recorded_target_encoding =
                        result_recorded_item.target.encoding;
                    let result_recorded_item_recorded_target_bytes_raw =
                        unsafe { result_recorded_item.target.bytes.0.as_slice()? };
                    let mut result_recorded_item_recorded_target_bytes =
                        Vec::with_capacity(result_recorded_item_recorded_target_bytes_raw.len());
                    for result_recorded_item_recorded_target_bytes_item_value in
                        result_recorded_item_recorded_target_bytes_raw
                    {
                        let result_recorded_item_recorded_target_bytes_item =
                            *result_recorded_item_recorded_target_bytes_item_value;
                        let result_recorded_item_recorded_target_bytes_item_recorded =
                            result_recorded_item_recorded_target_bytes_item;
                        result_recorded_item_recorded_target_bytes
                            .push(result_recorded_item_recorded_target_bytes_item_recorded);
                    }
                    let result_recorded_item_recorded_target_utf16_raw =
                        unsafe { result_recorded_item.target.utf16.0.as_slice()? };
                    let mut result_recorded_item_recorded_target_utf16 =
                        Vec::with_capacity(result_recorded_item_recorded_target_utf16_raw.len());
                    for result_recorded_item_recorded_target_utf16_item_value in
                        result_recorded_item_recorded_target_utf16_raw
                    {
                        let result_recorded_item_recorded_target_utf16_item =
                            *result_recorded_item_recorded_target_utf16_item_value;
                        let result_recorded_item_recorded_target_utf16_item_recorded =
                            result_recorded_item_recorded_target_utf16_item;
                        result_recorded_item_recorded_target_utf16
                            .push(result_recorded_item_recorded_target_utf16_item_recorded);
                    }
                    let result_recorded_item_recorded_target = fs::OsPathReplayRecord {
                        encoding: result_recorded_item_recorded_target_encoding,
                        bytes: result_recorded_item_recorded_target_bytes,
                        utf16: result_recorded_item_recorded_target_utf16,
                    };
                    let result_recorded_item_recorded_file_system =
                        unsafe { result_recorded_item.file_system.as_str()? }.to_string();
                    let result_recorded_item_recorded_flags = result_recorded_item.flags;
                    let result_recorded_item_recorded = MountEntryReplayRecord {
                        source: result_recorded_item_recorded_source,
                        target: result_recorded_item_recorded_target,
                        file_system: result_recorded_item_recorded_file_system,
                        flags: result_recorded_item_recorded_flags,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = OsMountListReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    OsMountListReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut value_native_values = Vec::with_capacity(value.len());
                    for value_native_item in value {
                        let value_native_item_native_source =
                            context.store_string(&value_native_item.source);
                        let value_native_item_native_target_encoding =
                            value_native_item.target.encoding;
                        let mut value_native_item_native_target_bytes_inner_values =
                            Vec::with_capacity(value_native_item.target.bytes.len());
                        for value_native_item_native_target_bytes_inner_item in
                            value_native_item.target.bytes
                        {
                            let value_native_item_native_target_bytes_inner_item_native =
                                value_native_item_native_target_bytes_inner_item;
                            value_native_item_native_target_bytes_inner_values
                                .push(value_native_item_native_target_bytes_inner_item_native);
                        }
                        let value_native_item_native_target_bytes_inner =
                            context.store_array(value_native_item_native_target_bytes_inner_values);
                        let value_native_item_native_target_bytes =
                            platform_fs::PathBytesAbi::<platform_abi::NativeAbi>(
                                value_native_item_native_target_bytes_inner,
                            );
                        let mut value_native_item_native_target_utf16_inner_values =
                            Vec::with_capacity(value_native_item.target.utf16.len());
                        for value_native_item_native_target_utf16_inner_item in
                            value_native_item.target.utf16
                        {
                            let value_native_item_native_target_utf16_inner_item_native =
                                value_native_item_native_target_utf16_inner_item;
                            value_native_item_native_target_utf16_inner_values
                                .push(value_native_item_native_target_utf16_inner_item_native);
                        }
                        let value_native_item_native_target_utf16_inner =
                            context.store_array(value_native_item_native_target_utf16_inner_values);
                        let value_native_item_native_target_utf16 =
                            platform_fs::PathUtf16Abi::<platform_abi::NativeAbi>(
                                value_native_item_native_target_utf16_inner,
                            );
                        let value_native_item_native_target = fs::OsPath {
                            encoding: value_native_item_native_target_encoding,
                            bytes: value_native_item_native_target_bytes,
                            utf16: value_native_item_native_target_utf16,
                        };
                        let value_native_item_native_file_system =
                            context.store_string(&value_native_item.file_system);
                        let value_native_item_native_flags = value_native_item.flags;
                        let value_native_item_native = MountEntry {
                            source: value_native_item_native_source,
                            target: value_native_item_native_target,
                            file_system: value_native_item_native_file_system,
                            flags: value_native_item_native_flags,
                        };
                        value_native_values.push(value_native_item_native);
                    }
                    let value_native = context.store_array(value_native_values);
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

